import { describe, it, expect } from 'vitest';
import { ChartCandlestick, Hammer, Wrench } from 'lucide-react';
import {
  mcpToolDisplayMap,
  mcpToolIconMap,
  getMcpToolIconName,
  resolveMcpToolIcon,
  resolveMcpToolLabel,
  isMcpToolName,
  getFormattedToolInput,
} from '@/config/mcpTools';

describe('mcpToolDisplayMap', () => {
  it('should contain expected tool mappings', () => {
    expect(mcpToolDisplayMap).toHaveProperty('mcp__chinabigdata__realtimeQuote');
    expect(mcpToolDisplayMap.mcp__chinabigdata__realtimeQuote).toBe('查询实时行情');
  });

  it('should contain query tools', () => {
    expect(mcpToolDisplayMap.mcp__chinabigdata__queryIndexAndObjectAndIndividual).toBe('搜索工具');
    expect(mcpToolDisplayMap.mcp__chinabigdata__getIndexSubject).toBe('搜索工具');
