      '获取指标数据',
    );
    expect(mcpToolDisplayMap.mcp__chinabigdata__batchQuerySubjects).toBe('获取专题数据');
  });
});

describe('mcpToolIconMap', () => {
  it('should map tools to correct icons', () => {
    expect(mcpToolIconMap.mcp__chinabigdata__queryIndexAndObjectAndIndividual).toBe('text-search');
    expect(mcpToolIconMap.mcp__chinabigdata__getIndexSubject).toBe('text-search');
    expect(mcpToolIconMap.mcp__chinabigdata__realtimeQuote).toBe('chart-candlestick');
    expect(mcpToolIconMap.mcp__chinabigdata__queryIndexByIndexIdIndividualId).toBe('square-sigma');
