describe('getMcpToolIconName', () => {
  it('should return hammer for undefined tool name', () => {
    expect(getMcpToolIconName(undefined)).toBe('hammer');
  });

  it('should return wrench for skill tools', () => {
    expect(getMcpToolIconName('skill')).toBe('wrench');
    expect(getMcpToolIconName('Skill')).toBe('wrench');
    expect(getMcpToolIconName('my-skill-tool')).toBe('wrench');
  });

  it('should return wrench when isSkill is true', () => {
    expect(getMcpToolIconName('any-tool', true)).toBe('wrench');
  });

  it('should return correct icon for known tools', () => {
    expect(getMcpToolIconName('mcp__chinabigdata__queryIndexAndObjectAndIndividual')).toBe(
      'text-search',
    );
    expect(getMcpToolIconName('mcp__chinabigdata__getIndexSubject')).toBe('text-search');
    expect(getMcpToolIconName('mcp__chinabigdata__realtimeQuote')).toBe('chart-candlestick');
  });

  it('should handle whitespace around tool names', () => {
    expect(getMcpToolIconName('  mcp__chinabigdata__realtimeQuote  ')).toBe('chart-candlestick');
  });

  it('should return hammer for unknown tools', () => {
    expect(getMcpToolIconName('unknown_tool')).toBe('hammer');
  });
});

describe('resolveMcpToolIcon', () => {
  it('should return a LucideIcon component', () => {
    const Icon = resolveMcpToolIcon('mcp__chinabigdata__realtimeQuote');
    // React 组件可以是函数或对象（forwardRef 返回对象）
    expect(Icon).toBeDefined();
    expect(typeof Icon === 'function' || typeof Icon === 'object').toBe(true);
  });

  it('should return different icons for different tools', () => {
    const Icon1 = resolveMcpToolIcon('mcp__chinabigdata__realtimeQuote');
    const Icon2 = resolveMcpToolIcon('mcp__chinabigdata__queryIndexAndObjectAndIndividual');
    expect(Icon1).not.toBe(Icon2);
  });

  it('should resolve known MCP tool icon from unified resolver', () => {
    expect(resolveMcpToolIcon('mcp__chinabigdata__realtimeQuote')).toBe(ChartCandlestick);
  });

  it('should resolve skill tool icon from unified resolver', () => {
    expect(resolveMcpToolIcon('skill')).toBe(Wrench);
    expect(resolveMcpToolIcon('any-tool', true)).toBe(Wrench);
  });

  it('should resolve unknown tool icon from unified resolver', () => {
    expect(resolveMcpToolIcon('unknown_tool')).toBe(Hammer);
  });
});

describe('resolveMcpToolLabel', () => {
  it('should return display name for known tools', () => {
    expect(resolveMcpToolLabel('mcp__chinabigdata__realtimeQuote')).toBe('查询实时行情');
    expect(resolveMcpToolLabel('mcp__chinabigdata__queryIndexAndObjectAndIndividual')).toBe(
      '搜索工具',
    );
    expect(resolveMcpToolLabel('mcp__chinabigdata__getIndexSubject')).toBe('搜索工具');
